<script lang="ts">
import ArchiveMaintenance from './ArchiveMaintenance.svelte';
import EvidenceKeys from './EvidenceKeys.svelte';
import {onMount} from 'svelte';import type {HealthSnapshot} from './api';import type {Language} from './i18n';import {formatTime} from './format';
let {health,connected,language}:{health:HealthSnapshot|null;connected:boolean;language:Language}=$props();const it=$derived(language==='it');let now=$state(Date.now());onMount(()=>{const timer=setInterval(()=>now=Date.now(),1000);return()=>clearInterval(timer);});
const usage=$derived(connected?health?.archive:null);const stale=$derived(!!usage && (now-usage.sampled_at_unix_ms>15000||usage.sampled_at_unix_ms>now+5000));const used=$derived(usage?.database_active_bytes??usage?.database_bytes??0);const pressure=$derived(!!usage && used>=usage.database_limit_bytes*0.9);const blocked=$derived(connected && health?.sensors.some(s=>s.id==='piko.storage' && s.state==='degraded'));const mib=(bytes:number)=>(bytes/1048576).toLocaleString(language,{maximumFractionDigits:1})+' MiB';
</script>
<section class="panel archive-panel"><div class="panel-heading"><div><h2>{it?'Capacità archivio':'Archive capacity'}</h2><p>{it?'Database e spazio riservato al registro transazioni':'Database and space reserved for the transaction log'}</p></div></div>
<ArchiveMaintenance {connected} {language}/>
<EvidenceKeys {connected} {language}/>
{#if !usage}
<p class="notice">{it?'Occupazione non disponibile: non significa che l’archivio sia vuoto.':'Usage unavailable: this does not mean the archive is empty.'} {health?.archive_error??''}</p>{:else}
{#if stale}<p class="warning">{it?'Campione non aggiornato.':'Sample is stale.'}</p>{/if}
{#if blocked}<p class="warning" role="status">{!stale && usage.database_active_bytes != null && usage.database_active_bytes >= usage.database_limit_bytes && usage.total_bytes < usage.budget_bytes ? (it ? 'Scritture sospese o fallite. È raggiunto il limite interno del database, anche se il budget complessivo non è esaurito. Le evidenze restano conservate.' : 'Writes paused or failed. The internal database limit is reached although the total budget is not exhausted. Existing evidence is retained.') : (it?'Scritture sospese o fallite: controlla il sensore piko.storage. Le evidenze esistenti restano conservate.':'Writes paused or failed: inspect piko.storage. Existing evidence is retained.')}</p>{/if}
<div class="reading"><strong>{mib(used)} / {mib(usage.database_limit_bytes)}</strong><span>{usage.database_active_bytes!=null?(it?'Spazio usato':'Used space'):(it?'Spazio allocato':'Allocated space')}</span><progress class:pressure max={usage.database_limit_bytes} value={Math.min(used,usage.database_limit_bytes)} aria-label={it?'Occupazione database':'Database usage'}></progress><small>{it?'File database allocato':'Allocated database file'}: {mib(usage.database_bytes)} · {it?'Totale file archivio':'Total archive files'}: {mib(usage.total_bytes)} · {it?'Budget configurato':'Configured budget'}: {mib(usage.budget_bytes)}</small></div>
{#if pressure}<p class="warning">{it?'Database vicino al limite interno. Il margine riservato al registro transazioni non equivale a spazio disponibile per altri eventi.':'Database near its internal limit. Reserved transaction-log capacity is not extra space for events.'}</p>{/if}
<p class="notice">{usage.retention_months?(it?`Conservazione: ${usage.retention_months} mesi. Eventi scaduti: ${usage.expired_events??0}.`:`Retention: ${usage.retention_months} months. Expired events: ${usage.expired_events??0}.`):(it?'Conservazione automatica disattivata.':'Automatic retention disabled.')}</p>
<p class="notice">{it?'Il budget comprende database, WAL/checkpoint e margine operativo. Il limite interno mostrato è letto da SQLite. La scadenza usa la data di raccolta. Il limite di spazio non accorcia il periodo di conservazione: se esaurito sospende le scritture.':'The budget includes the database, WAL/checkpoints and operating overhead. The internal limit shown is read from SQLite. Expiry uses collection time. Space limits never shorten retention: exhausted capacity pauses writes.'}</p><details><summary>{it?'Come cambiare il limite':'How to change the limit'}</summary><p>{it?'In modalità locale, arresta il monitor piko, conserva una copia di console.json in %LOCALAPPDATA%\\piko-monitor, modifica max_disk_mib (da 8 a 4096) e riapri Open-Piko.cmd. In modalità servizio serve un amministratore per service.json e il riavvio del solo servizio piko. Chiudere la UI non arresta il monitor.':'In local mode stop the piko monitor, back up console.json in %LOCALAPPDATA%\\piko-monitor, change max_disk_mib (8 to 4096), then reopen Open-Piko.cmd. Service mode requires an administrator for service.json and restarting the piko service. Closing the UI does not stop monitoring.'}</p></details><small class="sample">{it?'Campione':'Sample'}: {formatTime(usage.sampled_at_unix_ms,language)}</small>{/if}</section>
<style>.archive-panel{margin-bottom:22px}.reading{display:grid;gap:12px;padding:22px}.reading strong{font-size:1.2rem}.reading span,small,.notice,details{font-size:.76rem;color:var(--muted)}progress{width:100%;height:9px;accent-color:var(--accent)}progress.pressure{accent-color:var(--warning)}.notice,details,.sample{display:block;padding:12px 22px;line-height:1.6}.warning{padding:12px 22px;font-size:.78rem;background:var(--warning-surface);color:var(--warning)}summary{cursor:pointer}details p{line-height:1.6;overflow-wrap:anywhere}</style>
